import re
p='Assets/Game/Code/OnePit/Room/HallTheme.cs'
s=open(p,encoding='utf-8').read()
start=s.index('    /// Идентификаторы тем зала')
new='''    /// Тема зала «Тёмный сланец» (B): пол, лента, рамка зоны 1, обычная утка. Решение Максима 04.11: «сланец оставляем, убирай переключатель» —
    /// единственный вид зала. Параметры — из патча iter8d/vis/B/implementation.patch. Остальные темы (A/C/U/v6j), кнопка выбора, флаги
    /// `-pittThemes`/`-pittNoThemes`/`-pittTheme` и сохранение выбора удалены.
    public sealed class ThemeDef
    {
        public string Label;
        public Color FloorA, FloorB, FloorSeam;
        public int FloorMode; public float FloorW, FloorLen;
        public float SeamWidth, BevelWidth, NoiseAmt;
        public Color BeltCanvas, BeltSkirt, BeltPlank;
        public Color Zone1;
        /// Цвет обычной утки; DuckWing — доля клюва в крыле.
        public Color Duck; public float DuckWing;
    }

    public static class HallTheme
    {
        static ThemeDef _b;
        static bool _duckPushed;   // меши обычной утки построены с цветом темы

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        static void ResetStatics() { _b = null; _duckPushed = false; }

        /// До первой сцены: цвет утки должен стоять раньше, чем ModelLib построит её меш (прогрев на загрузке).
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
        static void Boot() { if (OnePitMode.Arg) { PushDuck(Cur); _duckPushed = true; } }

        static Color H(string s) => Palette.Hex(s);

        /// Единственная тема: B «Тёмный сланец» (плиты 4×4, режим 2, швы/фаски/шум из патча).
        public static ThemeDef Cur => _b ??= new ThemeDef
        {
            Label = "B Сланец",
            FloorA = H("#6E668C"), FloorB = H("#6A6288"), FloorSeam = H("#5D5578"), FloorMode = 2, FloorW = 4f, FloorLen = 4f,
            SeamWidth = 0.008f, BevelWidth = 0.012f, NoiseAmt = 0.015f,
            BeltCanvas = H("#4A4F68"), BeltSkirt = H("#3B3F54"), BeltPlank = H("#676E8F"), Zone1 = H("#8890B2"), Duck = H("#FFAA1D"), DuckWing = 0.24f,
        };

        // ------------------------------------------------------------------ значения для кода, который строит меши
        // Лента — во FlowV1/V2 (тема только во FlowV3) прежняя, как v6j.
        public static Color BeltCanvas => OnePitBalance.FlowV3 ? Cur.BeltCanvas : Pal.Rubber;
        public static Color BeltSkirt => OnePitBalance.FlowV3 ? Cur.BeltSkirt : Pal.Mix(Pal.Rubber, Palette.Ink, 0.35f);
        public static Color BeltPlank => OnePitBalance.FlowV3 ? Cur.BeltPlank : Pal.Mix(Pal.Rubber, Palette.Shade, 0.75f);
        public static Color Zone1 => Cur.Zone1;
        /// Манго-накладка и мягкий край были только у темы U (удалена): всегда выключены, бортик v6j.
        public static bool MangoOverlay => false;
        public static bool QuietEdge => false;

        static void PushDuck(ThemeDef t)
        {
            ModelLib.DuckColor = t.Duck;
            ModelLib.DuckWingMix = t.DuckWing;
        }

        /// Меши обычной утки соответствуют теме: если построены раньше (прогрев загрузки) — перекрасить.
        public static void EnsureDuck()
        {
            if (_duckPushed) return;
            PushDuck(Cur);
            _duckPushed = true;
            if (Game.IsSim) return;
            if (Game.Models is ModelLib lib) lib.RetintDuck();
            DuckInstancer.InvalidateDerived();
        }

        // ------------------------------------------------------------------ пол
        /// Пол зала (зовёт HallLook.Floor на постройке зала): цвета, режим, параметры материала.
        public static void ApplyFloor()
        {
            var t = Cur;
            Mats.SetFloorColors(t.FloorA, t.FloorB, t.FloorSeam);
            Mats.SetFloorStyle(t.FloorMode, t.FloorW, t.FloorLen);
            if (Game.IsSim) return;
            var m = Mats.Get(MatId.Floor);
            if (!m) return;
            m.SetFloat("_SeamWidth", t.SeamWidth);
            m.SetFloat("_BevelWidth", t.BevelWidth);
            m.SetFloat("_NoiseAmt", t.NoiseAmt);
        }

        /// Тест: параметры материала пола сейчас (шов, фаска, шум).
        public static Vector3 FloorParams()
        {
            var m = Game.IsSim ? null : Mats.Get(MatId.Floor);
            return m ? new Vector3(m.GetFloat("_SeamWidth"), m.GetFloat("_BevelWidth"), m.GetFloat("_NoiseAmt")) : Vector3.zero;
        }
    }
}
'''
s=s[:start]+new
s=s.replace('using System;\n','')
open(p,'w',encoding='utf-8').write(s)
